import React from 'react';

// Functional component
function Greeting(props) {
  return <h1>Hello, {props.name}!</h1>;
}

// Using useState hook
function Counter() {
  const [count, setCount] = React.useState(0);

  return (
    <div>
      <p>Count: {count}</p>
      <button onClick={() => setCount(count + 1)}>
        Increment
      </button>
    </div>
  );
}

// App component
function App() {
  return (
    <div>
      <Greeting name="Alice" />
      <Counter />
    </div>
  );
}

export default App;
